#!/usr/bin/env python3
# Blackout-Radar Schritt 2: Pushover bei Stufenwechsel, USV-Takt, Punkte auf /karte.
# Basis: Pi nach apply-blackout-radar-1b. Kein pip, kein apt.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PATCH = ("dashboard.py", "blackout_radar.py", "pushover_push.py", "lage_pages.py")
CHECK = ("blackout_radar_targets.json",)
PI = {
    "dashboard.py": ("8cbbf05158b7e3b8", 1388260),
    "lage_pages.py": ("80d2051f2143b0c1", 218549),
    "blackout_radar.py": ("e9f2c2f08fc826d4", 21066),
    "blackout_radar_targets.json": ("8b9b3f82db2b129d", 7488),
    "pushover_push.py": ("c80dc9451417a945", 11617),
}
MARKER = b"_PSH_ARM"

def load():
    raw = PAYLOAD
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw["pairs"][name]] for name in PATCH}

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def pi_ok(name, data: bytes) -> bool:
    kopf, laenge = PI[name]
    if not sha(data).startswith(kopf) or len(data) != laenge:
        return False
    if name == "dashboard.py":
        return MARKER in data and b"blackoutRadar1" in data and b"blackoutRadar2" not in data
    if name == "blackout_radar.py":
        return b"ALARM_S" not in data
    if name == "pushover_push.py":
        return b"radar_" not in data
    if name == "lage_pages.py":
        return b'id="borCard"' in data and b"blau:'#38bdf8'" not in data
    return True

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-bor2")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-bor2-*"))
    bak = path.with_name(path.name + ".bak-bor2-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare = load()
    namen = list(PATCH) + list(CHECK)
    for name in namen:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    blobs = {name: (ordner / name).read_bytes() for name in namen}
    for name in namen:
        print("%s basis sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    try:
        ziel = {name: verwandle(blobs[name], paare[name]) for name in PATCH}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    for name in CHECK:
        if not pi_ok(name, blobs[name]):
            print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
            return 2
        ziel[name] = blobs[name]
    for name in PATCH:
        print("%s endstand sha16 %s bytes %d" % (name, sha(ziel[name])[:16], len(ziel[name])))
    if all(blobs[name] == ziel[name] for name in namen):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    for name in PATCH:
        if ziel[name] == blobs[name]:
            continue
        if not pi_ok(name, blobs[name]):
            print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
            return 2
    if b"blackoutRadar2" not in ziel["dashboard.py"] or b"ALARM_S" not in ziel["blackout_radar.py"] or b"--neu-import" not in ziel["blackout_radar.py"]:
        print("STOP: Marker fehlt im Ergebnis")
        return 2
    if b"blau:'#38bdf8'" not in ziel["lage_pages.py"]:
        print("STOP: Kachel ohne Blau")
        return 2
    if b"radar_" not in ziel["pushover_push.py"]:
        print("STOP: Pushover ohne Radar")
        return 2
    for name in PATCH:
        try:
            compile(ziel[name], name, "exec")
        except SyntaxError as exc:
            print("STOP: Syntax %s %s" % (name, exc.lineno))
            return 2
    frei, meldung = fenster(jetzt)
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Import, kein Neustart")
        print("Befehl: python3 blackout_radar.py --neu-import")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
        return 0
    try:
        for name in PATCH:
            if blobs[name] == ziel[name]:
                continue
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. Radar-Stufenwechsel, Blau im Wachmodus, USV-Takt, Kartenpunkte.")
    import subprocess
    rc = subprocess.run([sys.executable, str(ordner / "blackout_radar.py"), "--neu-import"], cwd=str(ordner))
    if rc.returncode != 0:
        print("Import fehlgeschlagen. Erneut ohne Neustart: python3 blackout_radar.py --neu-import")
    else:
        print("Import einmalig gelaufen. Kein woechentlicher Refresh. Naechster Start macht einen Vollscan.")
    print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    import subprocess
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 13, 12, 12))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 0))[0] and not fenster(datetime(2026, 11, 13, 12, 4))[0]
    assert pi_ok("dashboard.py", b"_PSH_ARM blackoutRadar1") is False
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="bor2-apply-"))
    for name in list(PATCH) + list(CHECK):
        (ordner / name).write_bytes(b"UNBERUEHRT")
    vorher = {name: (ordner / name).read_bytes() for name in list(PATCH) + list(CHECK)}
    assert apply_dir(ordner, False, True, datetime(2026, 11, 13, 12, 12)) == 2
    assert {name: (ordner / name).read_bytes() for name in vorher} == vorher
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD = {"pairs":{"dashboard.py":[{"old":"","new":""}],"blackout_radar.py":[{"old":"","new":""}],"pushover_push.py":[{"old":"","new":""}],"lage_pages.py":[{"old":"","new":""}]}}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
